package org.localscape.nylocas.ranger;
import org.junit.Test;import org.localscape.nylocas.ranger.RangerStrategy.*;import static org.junit.Assert.*;
public class RangerIdleSouthTwentyRangeBackupTest {
 private Crab south;
 private Crab add(Room r,int key,int born,int wave,Lane lane,char slot,boolean big,Style style,int x,int y){Crab c=new Crab(key,key,born,wave,lane,slot,big,style,RangerStrategy.tile(x,y));c.pendingDamage=0;r.crabs.add(c);return c;}
 private Room room(){Room r=new Room();r.wave=22;r.spawns[20]=160;r.spawns[21]=176;r.spawns[22]=184;r.ready=194;r.player=RangerStrategy.tile(3295,4244);south=add(r,96,160,20,Lane.SOUTH,'W',true,Style.RANGE,3293,4243);south.hp=3;return r;}
 @Test public void anActualLocalSpareCanPipePermanentRangeWithoutMovingTheNextBow(){Room r=room();Decision d=new RangerStrategy().decide(r,194);assertSame(d.reason,south,d.target);assertEquals(Weapon.PIPE,d.weapon);assertEquals("Idle permanent-range South20 backup",d.reason);assertFalse(d.special);assertTrue(194+d.weapon.cooldown<=196);}
 @Test public void theVeryNextTickCannotConsumeSouthTwentyThreeBowBudget(){Room r=room();r.ready=195;assertNotSame(south,new RangerStrategy().decide(r,195).target);}
 @Test public void preTwentyOneAndMeleeAgeTwentyFiveAreOutsideTheBackup(){Room r=room();r.wave=20;r.ready=186;assertNotSame(south,new RangerStrategy().decide(r,186).target);r=room();r.ready=185;south.style=Style.MELEE;assertNotSame(south,new RangerStrategy().decide(r,185).target);}
 @Test public void normalOwnRangeAndMagicWorkRemainAheadOfTheBackup(){for(Style style:new Style[]{Style.RANGE,Style.MAGIC}){Room r=room();r.spawns[22]=188;Crab fresh=add(r,110,192,22,Lane.SPLIT,(char)0,false,style,3295,4245);assertSame(fresh,new RangerStrategy().decide(r,194).target);}}
 @Test public void anActualOtherSurvivorAndOwnWestTwentyAreNotDisplaced(){Room r=room();Crab fresh=add(r,110,192,22,Lane.SPLIT,(char)0,false,Style.RANGE,3295,4245);fresh.hp=1;RangerStrategy s=new RangerStrategy();s.attacked(new Decision(fresh,Weapon.PIPE,r.player,false,null,"actual"),192);assertSame(fresh,s.decide(r,194).target);r=room();Crab west=add(r,95,160,20,Lane.WEST,'S',true,Style.RANGE,3292,4248);assertSame(west,new RangerStrategy().decide(r,194).target);}
 @Test public void savedTwentyTwoDinhPrimaryIsUntouchedByTheSingleTargetBackup(){Room r=room();r.ready=192;Crab saved=add(r,108,184,22,Lane.SOUTH,'W',false,Style.MELEE,3294,4243);Decision d=new RangerStrategy().decide(r,192);assertSame(south,d.target);assertEquals(Weapon.PIPE,d.weapon);assertNotSame(saved,d.target);}
 @Test public void twentyOneBarragePrimaryIsNotTakenWhenItOwnsTheEarlyWindow(){Room r=room();r.wave=21;r.spawns[21]=192;r.ready=194;Crab saved=add(r,101,192,21,Lane.WEST,'S',false,Style.MAGIC,3294,4243);Decision d=new RangerStrategy().decide(r,194);assertSame(south,d.target);assertNotSame(saved,d.target);assertEquals(Weapon.PIPE,d.weapon);}
 @Test public void nullUnknownLethalClaimedBlockedAndDistantTargetsCannotBeUsed(){for(int g=0;g<6;g++){Room r=room();if(g==0)south.nulled=true;if(g==1)south.pendingDamage=-1;if(g==2)south.pendingDamage=3;if(g==3)south.provisionalClaimUntil=195;if(g==4)r.obstructed.add(south.key);if(g==5)south.point=RangerStrategy.tile(3301,4252);assertNotSame("guard"+g,south,new RangerStrategy().decide(r,194).target);}}
 @Test public void raisedCapHeadroomIncludesKnownOtherParentReplacements(){Room r=room();for(int i=0;i<22;i++)add(r,200+i,120,17,Lane.WEST,'S',true,Style.MELEE,3299,4252);assertNotSame(south,new RangerStrategy().decide(r,194).target);r=room();for(int i=0;i<21;i++)add(r,200+i,120,17,Lane.WEST,'S',true,Style.MELEE,3299,4252);Crab body=r.crabs.get(1);body.hp=0;body.dying=true;assertNotSame(south,new RangerStrategy().decide(r,194).target);}
 @Test public void theBackupEndsBeforeTwentyThreeAndNeverStagesDuringCooldown(){Room r=room();r.wave=23;r.spawns[23]=196;r.ready=198;assertNotSame(south,new RangerStrategy().decide(r,198).target);r=room();r.ready=195;assertNotSame(south,new RangerStrategy().decide(r,194).approach);}
}